public static class UiHarness // Check actual application commands while making the native Unity limitation explicit.
{ // Begin runtime and settings acceptance.
    private static int assertions; // Count only checks executed in this UI harness.
    private static void Require(bool value, string message) { assertions++; if (!value) throw new Exception(message); } // Stop on the first broken interaction contract.
    private static void Call(FoundationApp app, string name) { typeof(FoundationApp).GetMethod(name, BindingFlags.Instance | BindingFlags.NonPublic).Invoke(app, null); } // Invoke production lifecycle methods without duplicating their behavior.
    private static T Field<T>(FoundationApp app, string name) { return (T)typeof(FoundationApp).GetField(name, BindingFlags.Instance | BindingFlags.NonPublic).GetValue(app); } // Inspect effects on the real private application state.
    private static void Render(FoundationApp app, string click = "", UnityEngine.Event input = null) // Run one actual OnGUI pass with an explicit requested button or map event.
    { // Begin a controlled UI pass.
