            foreach (Outbreak.Contracts.HumanReaction response in new[] { Outbreak.Contracts.HumanReaction.Fight, Outbreak.Contracts.HumanReaction.Freeze, Outbreak.Contracts.HumanReaction.Flight }) // Verify every authored reaction scenario opens through the actual main menu.
            { // Begin one controlled UI scenario.
                FoundationApp reactionApp = new FoundationApp(); Call(reactionApp, "Awake"); Press(reactionApp, "Inspect " + response + " Paused"); Require(Field<TickClock>(reactionApp, "clock").Paused && Field<World>(reactionApp, "world").HumanReactions, "Reaction scenario failed to open paused."); Press(reactionApp, "Step 1 tick"); Require(Field<World>(reactionApp, "world").ActorAt(0).reaction == response, "Scenario UI did not produce the selected reaction."); foreach (int amount in new[] { 10, 50, 100 }) { long start = Field<World>(reactionApp, "world").Tick; Press(reactionApp, "Step " + amount + " ticks"); Require(Field<World>(reactionApp, "world").Tick == start + amount && Field<TickClock>(reactionApp, "clock").Paused, "Additional tick button advanced the wrong batch or resumed."); } Call(reactionApp, "OnDestroy"); // Every button drives real simulation steps through deferred dispatch.
            } // Finish controlled UI scenarios.
            FoundationApp groupApp = new FoundationApp(); Call(groupApp, "Awake"); Press(groupApp, "Inspect Group Support Paused"); Press(groupApp, "Step 1 tick"); Require(Field<World>(groupApp, "world").ActorAt(0).groupSupport == 6 && Field<World>(groupApp, "world").ActorAt(0).reaction == Outbreak.Contracts.HumanReaction.Fight, "Group-support button did not run the authored social-reaction fixture."); Call(groupApp, "OnDestroy"); // Verify the fourth controlled scenario uses the real reaction engine.
            FoundationApp menuApp = new FoundationApp(); Call(menuApp, "Awake"); Press(menuApp, "Inspect Freeze Paused"); Press(menuApp, "Step 1 tick"); Press(menuApp, "2x"); Press(menuApp, "Zoom +"); string retained = Documents.Encode(Field<World>(menuApp, "world").Capture()); World retainedWorld = Field<World>(menuApp, "world"); float retainedSpan = Field<float>(menuApp, "span"); Press(menuApp, "Run"); Render(menuApp); Require(!UnityEngine.GUILayout.controls["Step 1 tick"] && !UnityEngine.GUILayout.controls["Step 100 ticks"], "Running simulation exposed enabled manual steps."); // Do not queue a conflicting manual command during playback.
            UnityEditor.EditorApplication.isPaused = true; Render(menuApp, "Main Menu"); Require(!Field<bool>(menuApp, "showStart"), "Main Menu changed GUI state during the event."); UnityEditor.EditorApplication.Pump(); Require(Field<bool>(menuApp, "showStart") && Field<TickClock>(menuApp, "clock").Paused && Documents.Encode(Field<World>(menuApp, "world").Capture()) == retained, "Main Menu discarded or advanced the retained run."); UnityEditor.EditorApplication.isPaused = false; Press(menuApp, "Resume current run"); Require(object.ReferenceEquals(retainedWorld, Field<World>(menuApp, "world")) && Field<float>(menuApp, "span") == retainedSpan && Field<TickClock>(menuApp, "clock").Speed == 2 && !Field<TickClock>(menuApp, "clock").Paused && !Field<bool>(menuApp, "showStart"), "Resume replaced the world or lost camera, speed or playback."); // Resume must preserve the original instance and presentation settings.
            Press(menuApp, "Main Menu"); Press(menuApp, "Inspect Fight Paused"); Require(Field<bool>(menuApp, "confirmReset") && object.ReferenceEquals(retainedWorld, Field<World>(menuApp, "world")), "Menu scenario replaced the active run without confirmation."); Press(menuApp, "Keep current run"); Require(Documents.Encode(Field<World>(menuApp, "world").Capture()) == retained, "Canceled menu replacement lost state."); Press(menuApp, "Main Menu"); Press(menuApp, "Inspect Fight Paused"); Press(menuApp, "Replace run"); Require(Field<World>(menuApp, "world").Name == "Fight reaction test" && Field<TickClock>(menuApp, "clock").Paused, "Confirmed menu selection failed to open the requested scenario."); Call(menuApp, "OnDestroy"); // Verify both reset outcomes through real buttons rather than direct private calls.
            Require(FoundationApp.RuntimeButtonsAvailable, "Legacy input was incorrectly rejected."); Render(app); Require(UnityEngine.GUILayout.controls.ContainsKey("Start Movement Test") && Field<bool>(app, "showStart"), "No explicit start action."); // Require the startup screen to lead to the test.
            Render(app, "Start Movement Test"); Require(Field<bool>(app, "showStart"), "Start changed the GUI tree inside the current event."); Call(app, "Update"); Require(!Field<bool>(app, "showStart") && Field<World>(app, "world").Count == 25 && !Field<TickClock>(app, "clock").Paused, "Start did not create and run the 24+1 test."); // Verify real queued startup effects.
            UnityEngine.Time.unscaledDeltaTime = 0.2f; Call(app, "Update"); UnityEngine.Time.unscaledDeltaTime = 0; Require(Field<World>(app, "world").Tick == 1, "Started fixture did not tick."); Press(app, "Pause"); Require(Field<TickClock>(app, "clock").Paused, "Pause button failed."); long tick = Field<World>(app, "world").Tick; Press(app, "Step 10 ticks"); Require(Field<World>(app, "world").Tick == tick + 10, "Step button failed."); Press(app, "2x"); Require(Field<TickClock>(app, "clock").Speed == 2, "Speed button failed."); // Exercise actual time-control callbacks.
            UnityEditor.EditorApplication.isPaused = true; long executed = Field<long>(app, "executedActions"); Render(app, "Run"); Require(Field<Action>(app, "pendingAction") != null && Field<TickClock>(app, "clock").Paused, "Paused-editor command mutated state inside OnGUI."); UnityEditor.EditorApplication.Pump(); Require(!UnityEditor.EditorApplication.isPaused && !Field<TickClock>(app, "clock").Paused && Field<long>(app, "executedActions") == executed + 1, "Editor pause stranded the accepted Run action without Update."); Call(app, "Update"); Require(Field<long>(app, "executedActions") == executed + 1, "Editor and Update pumps executed one action twice."); Press(app, "Pause"); // Reproduce the paused-host queue bug and verify the real command executes exactly once through the editor callback.
            UnityEditor.EditorApplication.isPaused = true; tick = Field<World>(app, "world").Tick; Render(app, "Step 10 ticks"); UnityEditor.EditorApplication.Pump(); Require(Field<World>(app, "world").Tick == tick + 10 && UnityEditor.EditorApplication.isPaused, "Manual step could not execute while the host Update loop was paused."); UnityEditor.EditorApplication.isPaused = false; // Verify explicit stepping does not require or silently resume the host simulation loop.
            string folder = Path.Combine(Path.GetTempPath(), "OutbreakUi-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(folder); // Isolate real UI file-operation checks.
            try // Remove the finite test files after every success or failure.
            { // Begin native-boundary command checks.
                string mapPath = Path.Combine(folder, "small.obmap2"), runPath = Path.Combine(folder, "run.obsave2"); Documents.Write(mapPath, Documents.Encode(new WorldMap(2, 2).Capture())); UnityEditor.EditorUtility.openPath = mapPath; int opens = UnityEditor.EditorUtility.opens; Render(app, "Load Map"); Require(UnityEditor.EditorUtility.opens == opens, "Load opened its native dialog before OnGUI finished."); Call(app, "Update"); Require(UnityEditor.EditorUtility.opens == opens + 1 && Field<World>(app, "world").Count == 0 && Field<World>(app, "world").Width == 2, "Load Map did not replace the terrain candidate."); // Dispatch actual parsing and transactional replacement after the GUI event.
                Render(app); Require(!UnityEngine.GUILayout.controls["Run"], "Empty map offered a misleading running test."); Press(app, "Place human"); Render(app, "", new UnityEngine.Event { type = UnityEngine.EventType.MouseDown, button = 0, mousePosition = new UnityEngine.Vector2(42, 168) }); Require(Field<World>(app, "world").Count == 0, "Map placement mutated the GUI tree during the event."); Call(app, "Update"); Require(Field<World>(app, "world").Count == 1 && Field<World>(app, "world").ActorAt(0).x == 0 && Field<World>(app, "world").ActorAt(0).y == 0, "Manual human placement failed."); // Verify visible-cell conversion and deferred production spawning.
                Press(app, "Run"); Require(!Field<TickClock>(app, "clock").Paused, "Placed population could not run."); Press(app, "Pause"); UnityEditor.EditorUtility.savePath = runPath; Press(app, "Save Run"); Require(File.Exists(runPath) && Documents.ParseSave(Documents.Read(runPath)).Count == 1, "Save Run callback failed."); // Exercise actual saved state behind the substituted native dialog.
                Press(app, "Place zombie"); Press(app, "Cancel placement"); Require(!Field<Outbreak.Contracts.Species?>(app, "placing").HasValue, "Cancel placement failed."); UnityEditor.EditorUtility.openPath = ""; string before = Documents.Encode(Field<World>(app, "world").Capture()); Press(app, "Load Run"); Require(Documents.Encode(Field<World>(app, "world").Capture()) == before, "Canceled Load Run changed the population."); // Verify canceled commands preserve authoritative state.
