            Render(app, "Place human"); Require(UnityEditor.EditorApplication.update != null, "Deferred callback was not scheduled."); Call(app, "OnDestroy"); Require(UnityEditor.EditorApplication.update == null && Field<Action>(app, "pendingAction") == null, "Destroyed UI component retained queued editor work."); // Verify destruction cancels an accepted command before an editor or player pump executes it.
