            string message = "PASS UI dispatch/input-setup harness: " + assertions + " assertions. Narrow API doubles; actual Unity layout, native input and desktop dialogs remain unverified."; Console.WriteLine(message); if (args.Length == 1) File.AppendAllText(args[0], message + Environment.NewLine); return 0; // Record exactly what this host test establishes.
